-- Dibujo de cada trazado (layout.path) y trazados de Montmeló y Calafat.
--
-- path: LineString de PostGIS (SRID 4326, x = longitud, y = latitud) en el orden en que se
-- recorre la vuelta. Se guarda CERRADO (el último punto repite el primero) para que sea un
-- anillo válido en PostGIS; la API lo devuelve abierto (LayoutPathWkt hace la conversión).
-- Como mucho 200 puntos distintos (LayoutPath.MAX_POINTS). NULL = trazado aún sin dibujo.
--
-- ─────────────────────────────────────────────────────────────────────────────────────────
-- Geometría: © OpenStreetMap contributors, disponible bajo la Open Database License (ODbL)
-- https://www.openstreetmap.org/copyright — vías highway=raceway descargadas el 2026-11-20
-- (API 0.6 /map) y ensambladas por ids de nodo compartidos respetando oneway=yes;
-- simplificadas con Douglas-Peucker (2,5 m) y redondeadas a 6 decimales.
--
--   Montmeló GP              ways 831804327, 1560896065, 1560896066, 1560896061, 893732520, 831804325, 990483278
--   Montmeló GP con chicane  como GP, pero la chicane final: 1560896063, 1560896062, 1560896068, 1560896067
--   Montmeló Nacional        como GP, con el atajo 114293333 ("Catalunya (Cutting Half)")
--   Montmeló Escuela         831804327 + enlace 114293334 (sin nombre en OSM; 1709 m frente a 1650 m oficiales)
--   Calafat Principal        way 119486523 (anillo cerrado, sin oneway)
--
-- Longitud del dibujo (haversine con cierre) frente a length_m:
--   GP 4652 / 4657 · GP con chicane 4667 / 4675 · Nacional 2971 / 2977 · Escuela 1704 / 1650
--   Principal 3239 / 3250
-- Sentido: Montmeló, por oneway=yes de OSM (horario, como el GP del seed). Calafat no tiene
-- oneway en OSM y ninguna fuente publica el sentido; se toma HORARIO (inferido, por
-- confirmar con el circuito) porque es la única orientación del anillo con más curvas a
-- derechas que a izquierdas, coherente con las 9 der. / 7 izq. de la ficha oficial
-- (circuitcalafat.com), y la única en la que el atajo de la "Curva de Escuela" (way
-- 713130114) cae en la 3.ª curva y antes del que elimina las curvas 5-6-7 (way 713130115),
-- como en el orden de curvas oficial y en racingcircuits.info.
-- Calafat Corto: OSM no permite identificar su atajo; queda sin dibujo, longitud ni sentido.
-- ─────────────────────────────────────────────────────────────────────────────────────────

ALTER TABLE layout ADD COLUMN path geometry(LineString, 4326);

ALTER TABLE layout ADD CONSTRAINT ck_layout_path_ring
    CHECK (path IS NULL OR (ST_IsClosed(path) AND ST_NPoints(path) BETWEEN 4 AND 201));
ALTER TABLE layout ADD CONSTRAINT ck_layout_path_coordinates
    CHECK (path IS NULL OR (ST_XMin(path) >= -180 AND ST_XMax(path) <= 180
                            AND ST_YMin(path) >= -90 AND ST_YMax(path) <= 90));

-- Montmeló, pista de velocidad: variantes del GP
INSERT INTO layout (id, track_id, name, normalized_name, length_m, turns, direction, is_default, status, created_at) VALUES
    ('30000000-0000-4000-8000-000000000003', '20000000-0000-4000-8000-000000000001', 'GP con chicane', 'gp con chicane', 4675, NULL, 'CLOCKWISE', FALSE, 'VERIFIED', '2026-11-20T00:00:00Z'),
    ('30000000-0000-4000-8000-000000000004', '20000000-0000-4000-8000-000000000001', 'Nacional',       'nacional',       2977, NULL, 'CLOCKWISE', FALSE, 'VERIFIED', '2026-11-20T00:00:00Z'),
    ('30000000-0000-4000-8000-000000000005', '20000000-0000-4000-8000-000000000001', 'Escuela',        'escuela',        1650, NULL, 'CLOCKWISE', FALSE, 'VERIFIED', '2026-11-20T00:00:00Z');

